// (1) RACE CONDITION: two threads increment a shared counter unsafely.
int count = 0;
Runnable inc = () -> { for (int i = 0; i < 10000; i++) count++; };
Thread t1 = new Thread(inc), t2 = new Thread(inc);
t1.start(); t2.start(); t1.join(); t2.join();
//   count is likely < 20000 — lost updates (count++ is read+add+write, not atomic).
//   FIX: synchronize, or use AtomicInteger.

// (2) DEADLOCK: two threads each hold a lock the other needs.
Object a = new Object(), b = new Object();
new Thread(() -> { synchronized(a){ synchronized(b){ /* ... */ } } }).start();
new Thread(() -> { synchronized(b){ synchronized(a){ /* ... */ } } }).start();
//   t1 holds a, waits for b; t2 holds b, waits for a -> deadlock.
//   FIX: always lock in a consistent order (a then b).
